import type { ComponentProps, ReactNode } from 'react'
import { cn } from '@/lib/utils'
import styles from './Kbd.module.css'

/** One key as `children`, or a combination as `keys`: never both. */
export type KbdProps = Omit<ComponentProps<'kbd'>, 'children'> & { size?: 'sm' | 'md' } & (
    | { children: ReactNode; keys?: never }
    | { /** A key combination, one key cap per entry: `['⌘', 'K']`. */ keys: string[]; children?: never }
  )

export function Kbd({ keys, size = 'md', className, children, ...props }: KbdProps) {
  const cap = cn(styles.key, styles[size])
  if (!keys) {
    return (
      <kbd className={cn(cap, className)} {...props}>
        {children}
      </kbd>
    )
  }
  // HTML's own markup for a combination: a <kbd> of <kbd>s, one per key.
  return (
    <kbd className={cn(styles.group, className)} {...props}>
      {keys.map((key, i) => (
        <kbd key={i} className={cap}>
          {key}
        </kbd>
      ))}
    </kbd>
  )
}

/* A key cap: one glyph or word on a raised, bordered chip. It sits in a
   line of text, a tooltip or a menu row, so it inherits nothing from the
   UA's monospace <kbd> style. */
.key {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  padding-inline: var(--space-1);
  border: 1px solid var(--border);
  border-block-end-width: 2px;
  border-radius: var(--radius-sm);
  background: var(--muted);
  color: var(--muted-foreground);
  font-family: var(--font-sans);
  font-size: var(--text-body-xs);
  line-height: var(--leading-body-xs);
  font-weight: 500;
  white-space: nowrap;
  vertical-align: middle;
}

/* Small parts on the box ramp: md is xs (20px), sm is 2xs (16px). The
   minimum width equal to the height keeps a single glyph square. */
.md {
  min-inline-size: var(--box-xs);
  block-size: var(--box-xs);
}

.sm {
  min-inline-size: var(--box-2xs);
  block-size: var(--box-2xs);
  padding-inline: var(--space-0-5);
}

.group {
  display: inline-flex;
  align-items: center;
  gap: var(--space-0-5);
  font: inherit;
  vertical-align: middle;
}
